/** Browser presentation types; view identities are supplied by the application. */
/** Pixel size and CSS-to-device scaling for a view generation. */
export interface FrameForwardingViewport {
    version: number;
    width: number;
    height: number;
    deviceScaleFactor: number;
    visible: boolean;
}
/** Identity accompanying a shared image; generation matches the viewport version. */
export interface FrameForwardingFrameMetadata<Id extends string = string> {
    viewId: Id;
    requestId: string;
    frameId: number;
    generation: number;
    revision: number;
    width: number;
    height: number;
    tileKey?: string;
    /** Receiver-verified Windows source mutex; queued VideoFrame draws may release without CPU readback when true. */
    sourceKeyedMutex?: boolean;
    /** Highest canonical input sequence applied before this image; absent means the producer does not report it. */
    inputSequence?: number;
}
/** Borrowed shared VideoFrame; release after all consumer GPU reads finish. */
export interface FrameForwardingFrameLease<Id extends string = string> {
    transport: 'shared-texture';
    frame: VideoFrame;
    metadata: FrameForwardingFrameMetadata<Id>;
    /** Release once all consumer submissions referencing the frame have finished. */
    release(): void;
}
/** Captured pixels and the exact displayed image/viewport identities. */
export interface FrameForwardingCapture<Id extends string = string> {
    image: Blob;
    /** All contributing tile identities for a composite capture; metadata identifies the newest tile. */
    contributingFrames?: readonly FrameForwardingFrameMetadata<Id>[];
    metadata: FrameForwardingFrameMetadata<Id>;
    viewport: FrameForwardingViewport;
}
/** Explicit backend selection supports reproducible comparative measurements. */
export type FrameForwardingDisplayBackend = 'auto' | 'canvas2d' | 'webgpu' | 'webgl2';
/** Rendering operation owns no frame; its caller releases after completion. */
export interface FrameForwardingFramePainter {
    readonly backend: Exclude<FrameForwardingDisplayBackend, 'auto'>;
    readonly canvas: HTMLCanvasElement;
    /** Submit the image and resolve after the backend finishes reading it. */
    paint(frame: VideoFrame): Promise<void>;
    /** Release graphics resources; no further painting is permitted. */
    dispose(): void;
}
